#include <algorithm>
#include <string>
#include <string_view>
#include <vector>

class TodoList
{
public:
    int add(std::string_view title)
    {
        if (title.empty())
        {
            return 0;
        }
        m_tasks.push_back(Task{ ++m_lastId, std::string{ title }, false });
        return m_lastId;
    }

    bool complete(int id)
    {
        for (Task& task : m_tasks)
        {
            if (task.id == id)
            {
                if (task.done)
                {
                    return false;
                }
                task.done = true;
                return true;
            }
        }
        return false;
    }

    bool remove(int id)
    {
        const auto before{ m_tasks.size() };
        std::erase_if(m_tasks, [id](const Task& task) { return task.id == id; });
        return m_tasks.size() != before;
    }

    int pending() const
    {
        return static_cast<int>(std::count_if(m_tasks.begin(), m_tasks.end(), [](const Task& task) { return !task.done; }));
    }

    int total() const { return static_cast<int>(m_tasks.size()); }

    std::vector<std::string> titles(bool onlyPending) const
    {
        std::vector<std::string> result{};
        for (const Task& task : m_tasks)
        {
            if (!onlyPending || !task.done)
            {
                result.push_back(task.title);
            }
        }
        return result;
    }

private:
    struct Task
    {
        int id{};
        std::string title{};
        bool done{ false };
    };

    std::vector<Task> m_tasks{};
    int m_lastId{ 0 };
};

