using Titles = std::vector<std::string>;
TEST("adding gives ids from 1") { TodoList t{}; CHECK_EQ(t.add("Buy milk"), 1); CHECK_EQ(t.add("Write code"), 2); CHECK_EQ(t.total(), 2); CHECK_EQ(t.pending(), 2); }
TEST("empty titles are refused") { TodoList t{}; CHECK_EQ(t.add(""), 0); CHECK_EQ(t.total(), 0); CHECK_EQ(t.add("real"), 1); }
TEST("completing") { TodoList t{}; t.add("a"); t.add("b"); CHECK(t.complete(1)); CHECK(!t.complete(1)); CHECK(!t.complete(99)); CHECK_EQ(t.pending(), 1); CHECK_EQ(t.total(), 2); }
TEST("removing") { TodoList t{}; t.add("a"); t.add("b"); CHECK(t.remove(1)); CHECK(!t.remove(1)); CHECK_EQ(t.total(), 1); CHECK_EQ(t.titles(false), (Titles{ "b" })); }
TEST("ids are never reused") { TodoList t{}; t.add("a"); t.add("b"); t.remove(2); CHECK_EQ(t.add("c"), 3); }
TEST("titles") { TodoList t{}; t.add("a"); t.add("b"); t.add("c"); t.complete(2); CHECK_EQ(t.titles(false), (Titles{ "a", "b", "c" })); CHECK_EQ(t.titles(true), (Titles{ "a", "c" })); }
TEST("readers work on a const list") { TodoList t{}; t.add("x"); const TodoList& view{ t }; CHECK_EQ(view.total(), 1); CHECK_EQ(view.pending(), 1); CHECK_EQ(view.titles(true).size(), 1u); }

